path_specs=[('PATH-BEGINNER','Absolute Beginner',['M01','B01','M21','M03','M22','M04','M05','M24','M10','M45','M60'],'No prior finance; basic reading and arithmetic, B01 includes safety bridge.','Explain contract obligations, compute net payoff and size a synthetic position.',['M25','M62','M63']),('PATH-RETAIL','Retail Options Trader',['M25','M32','M34','M35','M36','M38','M45','M47','M49','M52','M53','M61','M65'],'Beginner exit or equivalent diagnostic.','Write a falsifiable costed strategy dossier and manage a simulated lifecycle.',['M15','M27','M62','M63']),('PATH-QUANT','Quantitative Options Trader',['B03','M58','M13','M14','M31','M33','M37','M40','M54','M55','M56','M46'],'Algebra and probability diagnostic; bridge calculus and Python as needed.','Validate pricing/calibration and an out-of-sample research experiment.',['M43','M44','M57']),('PATH-VOL','Volatility Trader',['M34','M35','M36','M37','M38','M39','M41','M47','M52','M55','M56'],'Contract, Greek and inference diagnostics.','Separate variance premium, forecast, hedge error and execution costs.',['M40','M44','M51']),('PATH-MM','Market-Making',['M50','M51','M33','M37','M47','M49','M52','M54','M56','M67'],'Pricing, probability and executable-code diagnostics.','Run a simulated inventory/quoting desk with adverse-selection and recovery controls.',['M40','M43','M44']),('PATH-INDIA','Indian Options Trader',['M25','M45','M47','M49','M63','M32','M34','M52','M53','M61','M65'],'Beginner exit or bridge; no current contract facts assumed.','Reconcile dated index/stock obligations and costs using circular and contract evidence.',['M38','M39','M64']),('PATH-SYSTEMATIC','Systematic Options Trader',['B03','M58','M54','M55','M56','M48','M49','M59','M61','M67'],'Probability, contract and Python diagnostics.','Reproduce a research-to-simulation pipeline with capital and operational constraints.',['M12','M57','M41'])]
