# An exhaustive archival map for all original entities and relationships; raw sources immutable.
maprows=[]
def mapped(id,kind,loc,target,disposition='retained',note='Original text preserved; canonical scope/design is not a reviewed lesson.'):
 maprows.append({'id':'MAP-'+id,'original_id':id,'kind':kind,'provenance':loc,'canonical_ids':target,'disposition':disposition,'note':note})
for m in mi[:67]:mapped(m['id'],'module',m['provenance'],[m['id']])
for t in ti[:1019]:
 mapped(t['id'],'topic',t['provenance'],[t['id']]);mapped(t['id']+'-scope','subtopic_scope',t['provenance'],[t['id']+'.S01'])
for r in ri:mapped(r['id'],'resource',r['provenance'],[r['id']])
for s in si:mapped('STAGE-'+str(s['stage']),'sequence',{'source':'sources/roadmaps/options-curriculum-catalog.json','json_pointer':'/stages/'+str(s['stage'])},['OLD-STAGE-'+str(s['stage'])],'archived_navigation','Original sequence preserved; competency paths permit earlier contracts, risk and coding.')
for m in mi[:67]:
 mapped(m['id']+'-assessment','exercise_checkpoint',m['provenance'],['EX-'+m['id']+'-P','QZ-'+m['id']]);
 for p in m['prerequisites']:mapped(m['id']+'-prereq-'+p,'prerequisite',m['provenance'],['C-'+m['id'],'C-'+p],'reclassified','Original edge preserved here; canonical hard/recommended separation controls entry.')
 for rid in m['sources']:mapped(m['id']+'-resource-'+rid,'module_resource',m['provenance'],[m['id'],rid],'archived_context','Original broad association is not an exact citation.')
for t in ti[:1019]:
 for rid in t['sources']:mapped(t['id']+'-resource-'+rid,'inherited_topic_resource',t['provenance'],[t['id'],rid],'archived_context','Inherited link preserved but not promoted to a claim-level citation.')
for k,v in su.items():mapped('SUP-'+k,'supplemental',{'source':v['source'],'line':v['line']},['SUP-'+k])
for d in sorted({m['domain'] for m in mi[:67]}):mapped(d.split(' · ')[0],'domain',{'source':'research/inventory/modules.json','selector':d},[d.split(' · ')[0]])
export('source_mappings',maprows)
